var t=[{title:`Roeitechniek`,text:`Begin vanuit een stabiele positie en trek naar je onderste ribben of heup, afhankelijk van de oefening. Laat je schouderbladen vanzelf bewegen als je armen uitreiken en terugtrekken, en gooi je romp niet mee om momentum op te bouwen. Je hoeft je ellebogen niet in één hoek te forceren, en het bereik eindigt waar je het nog kunt beheersen.`},{title:`Variaties met materiaal`,text:`Een roeibeweging met één dumbbell werkt elke kant afzonderlijk, en je kunt een hand op een stevige bank laten rusten voor steun. Bij zittend roeien aan de kabel kun je het gewicht in kleine stappen aanpassen. Roeien met een band vraagt een stevig anker, en de weerstand verandert gedurende de herhaling. Omgekeerd roeien met lichaamsgewicht wordt makkelijker naarmate je lichaam meer rechtop staat en zwaarder naarmate het dichter bij horizontaal komt.`},{title:`Wat de moeilijkheid verandert`,text:`Romphoek, steun, handvatbreedte, elleboogpad, gewicht en bewegingsbereik veranderen allemaal hoe zwaar een roeibeweging is. Een roeibeweging met steun voor de borst neemt de noodzaak weg om een voorovergebogen heupscharnier vast te houden, wat helpt als je je rug wilt trainen en niet je uithoudingsvermogen in het heupscharnier. Het is ook een goede keuze als een lang heupscharnier vasthouden niet bij je past. Log verschillende roeivarianten apart, want hun getallen zijn niet uitwisselbaar.`},{title:`Typische fouten`,text:`Vermijd hard optrekken van de schouders, rukken met je onderrug of het bereik inkorten om meer te tillen. Als je positie wegglijdt, verlicht dan het gewicht en vertraag de daalfase. Roeien thuis met een tafel of een handdoek is alleen veilig als het anker en de constructie je bewegende lichaamsgewicht betrouwbaar kunnen houden.`},{title:`Je week plannen`,text:`Koppel roeibewegingen aan horizontale persen over de week. Kies roeivarianten die passen bij je uitrusting, waar je een band veilig kunt verankeren en de gewichten die je hebt.`}];var i=[{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: techniek bij krachttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`NSCA: basis van veiligheid en krachttraining`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};